import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import { registerActivityListeners, listActivity } from "@/server/services/activity-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

it("moves", async () => {
  const t = await createTenant("mv");
  const off = registerActivityListeners();
  const ops = await projectService.createProject(t.actors.admin, { orgId: t.org.id, name: "Ops", slug: "ops", key: "OPS", description: null, visibility: "org", leadId: null, color: "#000000", targetDate: null } as never);
  const a = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
  const b = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
  const seen: unknown[] = [];
  const off2 = subscribe("issue.moved", (p) => { seen.push(p); });
  const same = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: b.id, toProjectId: t.project.id });
  expect(same).toEqual(b); expect(seen).toHaveLength(0);
  const moved = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: b.id, toProjectId: ops.id });
  expect(moved.projectId).toBe(ops.id); expect(moved.number).toBe(1);
  expect(seen).toHaveLength(1);
  expect(await issueRepo.nextIssueNumber(t.org.id, t.project.id)).toBe(3);
  const back = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: b.id, toProjectId: t.project.id });
  expect(back.number).toBe(3);
  await expect(issueService.moveIssueToProject(t.actors.viewer, { orgId: t.org.id, issueId: a.id, toProjectId: ops.id })).rejects.toThrow();
  const page = await listActivity(t.actors.admin, { orgId: t.org.id, action: ["issue.moved"], limit: 25, cursor: null });
  expect(page.items).toHaveLength(2);
  expect(page.items.find((e) => e.projectId === ops.id)?.metadata).toMatchObject({ fromNumber: 2, toNumber: 1 });
  off(); off2();
});
